INSERT OR IGNORE INTO game_settings (key, value, value_type, description)
     VALUES ('branding', '{"gameName":"World War","welcomeTitle":"🌍 به World War خوش آمدید!","welcomeText":"🌍 به World War خوش آمدید!\n\nکشور خود را بسازید، اقتصاد آن را توسعه دهید، ارتش بچینید و در جنگ‌های جهانی شرکت کنید.\nبرای شروع «ایجاد کشور» را بزنید.","nationNamePrompt":"✍️ نام کشور خود را ارسال کنید (۳ تا ۳۰ نویسه، یکتا):","leaderNamePrompt":"✍️ نام رئیس کشور را ارسال کنید (۲ تا ۴۰ نویسه):","flagPrompt":"🚩 پرچم کشور خود را انتخاب کنید:","statementPrompt":"📜 صدور بیانیه\n\nلطفاً متن بیانیه خود را ارسال کنید.\n\nبیانیه شما پس از ثبت، به عنوان موضع رسمی کشور شما منتشر خواهد شد.\n\n✍️ متن بیانیه را در یک پیام ارسال کنید."}', 'json', 'seed default');
